"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[395],{1683:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a new hierarchical state machine.\\n\\n```lua\\nlocal hsm = Stratix.new()\\n```","params":[],"returns":[{"desc":"","lua_type":"HSM"}],"function_type":"static","source":{"line":51,"path":"docs/Stratix.lua"}},{"name":"AddRegion","desc":"Registers a parallel region. Each region runs its own active state\\nindependently. Must be called before `Start` unless you intend to boot it\\nlater with `StartRegion`.\\n\\n```lua\\nhsm:AddRegion(\\"Movement\\", \\"Idle\\")\\nhsm:AddRegion(\\"Weapon\\")\\n```","params":[{"name":"name","desc":"Unique region name.","lua_type":"string"},{"name":"initialState","desc":"Default initial state for this region.","lua_type":"string?"}],"returns":[],"function_type":"method","source":{"line":92,"path":"docs/Stratix.lua"}},{"name":"AddState","desc":"Registers a state. If `parentName` is provided the state is nested under\\nthat parent and inherits its region. If `regionName` is provided the state\\nis placed in that region as a top-level state. If neither is given, Stratix\\ncreates and uses the implicit `\\"Default\\"` region.\\n\\n```lua\\nhsm:AddState(\\"Idle\\")\\n\\nhsm:AddState(\\"Moving\\", nil, { Initial = \\"Walking\\" })\\nhsm:AddState(\\"Walking\\",  \\"Moving\\")\\nhsm:AddState(\\"Sprinting\\", \\"Moving\\")\\n\\nhsm:AddState(\\"Unarmed\\", nil, nil, \\"Weapon\\")\\n```","params":[{"name":"name","desc":"Unique state name.","lua_type":"string"},{"name":"parentName","desc":"Parent state name, if nested.","lua_type":"string?"},{"name":"config","desc":"Entry/exit callbacks and history settings.","lua_type":"StateConfig?"},{"name":"regionName","desc":"Region to place the state in (top-level states only).","lua_type":"string?"}],"returns":[{"desc":"The state name, for convenience.","lua_type":"string"}],"function_type":"method","source":{"line":119,"path":"docs/Stratix.lua"}},{"name":"AddTransition","desc":"Registers a transition from `fromName` to `toName` triggered by `event`.\\nBoth states must be in the same region. Multiple transitions can share the\\nsame event; guards are tested in registration order.\\n\\n```lua\\n-- Basic\\nhsm:AddTransition(\\"Idle\\", \\"RUN\\", \\"Running\\")\\n\\n-- With guard\\nhsm:AddTransition(\\"Running\\", \\"JUMP\\", \\"Airborne\\", {\\n    Guard = function(self) return self.Stamina > 0 end,\\n})\\n\\n-- With action (runs between OnExit and OnEntry)\\nhsm:AddTransition(\\"Idle\\", \\"ATTACK\\", \\"Attacking\\", {\\n    Action = function(self) self.AttackCount += 1 end,\\n})\\n\\n-- Internal (action only, no exit/entry)\\nhsm:AddTransition(\\"Idle\\", \\"PING\\", \\"Idle\\", {\\n    Internal = true,\\n    Action   = function(self) print(\\"ping\\") end,\\n})\\n```","params":[{"name":"fromName","desc":"Source state.","lua_type":"string"},{"name":"event","desc":"Event string that triggers this transition.","lua_type":"string"},{"name":"toName","desc":"Target state.","lua_type":"string"},{"name":"config","desc":"Optional guard, action, and internal flag.","lua_type":"TransitionConfig?"}],"returns":[],"function_type":"method","source":{"line":155,"path":"docs/Stratix.lua"}},{"name":"ReplaceTransitionGuard","desc":"Replaces the guard on an existing transition at runtime. `index` is\\n1-based and matches registration order for that event on that state.\\n\\n```lua\\nhsm:ReplaceTransitionGuard(\\"Running\\", \\"JUMP\\", 1, function(self)\\n    return self.Stamina > 10\\nend)\\n```","params":[{"name":"fromName","desc":"","lua_type":"string"},{"name":"event","desc":"","lua_type":"string"},{"name":"index","desc":"1-based index in the transition list for this event.","lua_type":"number"},{"name":"newGuard","desc":"","lua_type":"(hsm: HSM) -> boolean"}],"returns":[],"function_type":"method","source":{"line":175,"path":"docs/Stratix.lua"}},{"name":"Extend","desc":"Passes the HSM to `builderFn`, allowing you to modularize setup.\\n\\n```lua\\nlocal function addMovement(h)\\n    h:AddState(\\"Idle\\")\\n    h:AddState(\\"Running\\")\\n    h:AddTransition(\\"Idle\\", \\"RUN\\", \\"Running\\")\\nend\\n\\nhsm:Extend(addMovement)\\n```","params":[{"name":"builderFn","desc":"","lua_type":"(hsm: HSM) -> ()"}],"returns":[],"function_type":"method","source":{"line":195,"path":"docs/Stratix.lua"}},{"name":"Start","desc":"Boots all registered regions and begins processing events. Can only be\\ncalled once. Pass a state name for single-region machines, or a table\\nmapping region names to initial states for multi-region machines.\\n\\n```lua\\n-- Single region\\nhsm:Start(\\"Idle\\")\\n\\n-- Multiple regions\\nhsm:Start({ Movement = \\"Walking\\", Weapon = \\"Unarmed\\" })\\n```","params":[{"name":"initialStates","desc":"Initial state(s).","lua_type":"({ [string]: string } | string)?"}],"returns":[],"function_type":"method","source":{"line":215,"path":"docs/Stratix.lua"}},{"name":"StartRegion","desc":"Boots a region that was added after `Start`. All states and transitions for\\nthe region must be registered before calling this.\\n\\n```lua\\nhsm:AddRegion(\\"Emote\\")\\nhsm:AddState(\\"Idle_Emote\\", nil, nil, \\"Emote\\")\\nhsm:StartRegion(\\"Emote\\", \\"Idle_Emote\\")\\n```","params":[{"name":"regionName","desc":"","lua_type":"string"},{"name":"initialState","desc":"Overrides the region\'s registered initial state.","lua_type":"string?"}],"returns":[],"function_type":"method","source":{"line":233,"path":"docs/Stratix.lua"}},{"name":"Dispatch","desc":"Sends an event to all regions. Each region walks its active state\'s\\nancestor chain and fires the first matching transition whose guard passes.\\n\\nEvents dispatched while a transition is in progress are queued and\\nreplayed in order after the current transition completes.\\n\\n```lua\\nlocal handled = hsm:Dispatch(\\"RUN\\")\\n```","params":[{"name":"event","desc":"","lua_type":"string"}],"returns":[{"desc":"`true` if at least one region handled the event.","lua_type":"boolean"}],"function_type":"method","source":{"line":252,"path":"docs/Stratix.lua"}},{"name":"GetActive","desc":"Returns the active state name for every region.\\n\\n```lua\\nlocal active = hsm:GetActive()\\n-- { Default = \\"Running\\", Weapon = \\"Armed\\" }\\n```","params":[],"returns":[{"desc":"","lua_type":"{ [string]: string }"}],"function_type":"method","source":{"line":267,"path":"docs/Stratix.lua"}},{"name":"GetActiveIn","desc":"Returns the active state name in the given region, or `nil` if the region\\nhas not been started.\\n\\n```lua\\nlocal state = hsm:GetActiveIn(\\"Weapon\\")   --\x3e \\"Armed\\"\\n```","params":[{"name":"regionName","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"string?"}],"function_type":"method","source":{"line":283,"path":"docs/Stratix.lua"}},{"name":"IsActive","desc":"Returns `true` if `name` is the active state or an active ancestor state\\nin any region.\\n\\n```lua\\nhsm:IsActive(\\"Moving\\")   --\x3e true when Walking or Sprinting is active\\n```","params":[{"name":"name","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","source":{"line":299,"path":"docs/Stratix.lua"}},{"name":"IsActiveIn","desc":"Returns `true` if `name` is the active state or an active ancestor state\\nin the specified region.\\n\\n```lua\\nhsm:IsActiveIn(\\"Moving\\", \\"Default\\")\\n```","params":[{"name":"name","desc":"","lua_type":"string"},{"name":"regionName","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","source":{"line":316,"path":"docs/Stratix.lua"}},{"name":"GetStateNames","desc":"Returns a sorted list of all registered state names, optionally filtered\\nto one region. Root sentinel states are excluded.\\n\\n```lua\\nhsm:GetStateNames()            -- all regions\\nhsm:GetStateNames(\\"Movement\\")  -- one region\\n```","params":[{"name":"regionName","desc":"Filter to this region.","lua_type":"string?"}],"returns":[{"desc":"","lua_type":"{ string }"}],"function_type":"method","source":{"line":333,"path":"docs/Stratix.lua"}},{"name":"Destroy","desc":"Destroys the HSM. Runs `OnExit` on all currently active states, then\\ndisconnects all signals and clears internal state. The HSM cannot be used\\nafter this call.\\n\\n```lua\\nhsm:Destroy()\\n```","params":[],"returns":[],"function_type":"method","source":{"line":347,"path":"docs/Stratix.lua"}}],"properties":[{"name":"Signals","desc":"Top-level Signal connections for the HSM.\\n\\n| Signal | Parameters | Fires when |\\n|--------|-----------|------------|\\n| `OnStateChanged` | `prev: string?, next: string, region: string` | A state becomes active |\\n| `OnTransition` | `from: string, event: string, to: string, region: string` | A transition completes (including internal) |\\n\\n```lua\\nhsm.Signals.OnStateChanged:Connect(function(prev, next, region)\\n    print(region, prev, \\"->\\", next)\\nend)\\n\\nhsm.Signals.OnTransition:Connect(function(from, event, to, region)\\n    print(event, from, \\"->\\", to)\\nend)\\n```","lua_type":"StoreSignals","source":{"line":74,"path":"docs/Stratix.lua"}}],"types":[],"name":"Stratix","desc":"Hierarchical state machine for Roblox Luau.\\n\\nStratix models behavior as a tree of named states connected by guarded\\ntransitions. Dispatching an event walks the active state\'s ancestor chain\\nand fires the first transition whose guard passes. It supports nested\\nstates, parallel regions, shallow/deep history, internal transitions,\\nentry/exit callbacks, guards, actions, and an event queue.\\n\\nRequires a Signal implementation at\\n`ReplicatedStorage.Shared.Modules.Utilities.Signal`.\\n\\n```lua\\nlocal Stratix = require(ReplicatedStorage.Stratix)\\n\\nlocal hsm = Stratix.new()\\n\\nhsm:AddState(\\"Idle\\", nil, {\\n    OnEntry = function(self) print(\\"Idle\\") end,\\n    OnExit  = function(self) print(\\"Leaving Idle\\") end,\\n})\\nhsm:AddState(\\"Running\\")\\n\\nhsm:AddTransition(\\"Idle\\",    \\"RUN\\",  \\"Running\\")\\nhsm:AddTransition(\\"Running\\", \\"STOP\\", \\"Idle\\")\\n\\nhsm:Start(\\"Idle\\")\\nhsm:Dispatch(\\"RUN\\")\\n```","source":{"line":37,"path":"docs/Stratix.lua"}}')}}]);